import OpenAI from "openai";
import fs from "fs";

const client = new OpenAI({
  apiKey: process.env.DASHSCOPE_API_KEY,
  baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
});

const fileObject = await client.files.create({
  file: fs.createReadStream("input.jsonl"),
  purpose: "batch",
});

console.log(`File ID: ${fileObject.id}`);

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.DASHSCOPE_API_KEY,
  baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
});

const batch = await client.batches.create({
  input_file_id: "file-abc123",
  endpoint: "/v1/chat/completions",
  completion_window: "24h",
});

console.log(`Batch ID: ${batch.id}`);
console.log(`Status: ${batch.status}`);

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.DASHSCOPE_API_KEY,
  baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
});

const batches = await client.batches.list({ limit: 2 });

for (const batch of batches.data) {
  console.log(batch.id, batch.status);
}

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.DASHSCOPE_API_KEY,
  baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
});

const batch = await client.batches.retrieve("batch_abc123");

console.log(`Status: ${batch.status}`);
console.log(`Output file: ${batch.output_file_id}`);
console.log(`Error file: ${batch.error_file_id}`);

import OpenAI from "openai";

const client = new OpenAI({
  apiKey: process.env.DASHSCOPE_API_KEY,
  baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
});

const batch = await client.batches.cancel("batch_abc123");

console.log(`Status: ${batch.status}`);

import OpenAI from "openai";
import fs from "fs";

const client = new OpenAI({
  apiKey: process.env.DASHSCOPE_API_KEY,
  baseURL: "https://dashscope.aliyuncs.com/compatible-mode/v1",
});

const content = await client.files.content("file-xyz789");
const text = await content.text();
fs.writeFileSync("result.jsonl", text);
